#!/usr/bin/env bash
# CPP-OMS-001: prove generation WITHOUT --with-codec is unchanged.
#
# Runs a baseline CLI (built from the pre-change main commit) and a candidate
# CLI over every tests/fixtures/service-generate schema/contract pair that
# shares a stem, for service-check and service-generate, in cpp, rust and ada,
# without the codec flag; and for service-check --with-codec in rust and ada
# (their codec readiness must not move). Exit codes, stdout (with the output
# directory normalised) and every generated byte must be identical.
#
# Usage: scripts/check-cpp-oms-001-parity.sh BASELINE_CLI CANDIDATE_CLI [scratch]
set -euo pipefail
if [[ $# -lt 2 ]]; then
  echo 'usage: scripts/check-cpp-oms-001-parity.sh BASELINE_CLI CANDIDATE_CLI [scratch]' >&2
  exit 2
fi
baseline="$(realpath "$1")"
candidate="$(realpath "$2")"
repo="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
scratch="${3:-$(mktemp -d)}"
mkdir -p "$scratch"
cd "$repo/tests/fixtures/service-generate"
pairs=0
runs=0
mismatches=0
compare() { # label, then the command arguments (output directory appended last)
  local label="$1"; shift
  local out_b out_c code_b=0 code_c=0
  rm -rf "$scratch/b" "$scratch/c"
  out_b="$("$baseline" "$@" --output "$scratch/b" 2>&1)" || code_b=$?
  out_c="$("$candidate" "$@" --output "$scratch/c" 2>&1)" || code_c=$?
  out_b="${out_b//"$scratch/b"/OUT}"
  out_c="${out_c//"$scratch/c"/OUT}"
  runs=$((runs + 1))
  local same=1
  [[ "$code_b" == "$code_c" && "$out_b" == "$out_c" ]] || same=0
  if [[ -e "$scratch/b" || -e "$scratch/c" ]]; then
    diff -r "$scratch/b" "$scratch/c" >/dev/null 2>&1 || same=0
  fi
  if [[ "$same" == 0 ]]; then
    echo "MISMATCH: $label"
    mismatches=$((mismatches + 1))
  fi
}
for schema in *.xsd; do
  stem="${schema%.xsd}"
  contract="$stem.yaml"
  [[ -f "$contract" ]] || continue
  pairs=$((pairs + 1))
  for language in cpp rust ada; do
    base=(--schema "$schema" --contract "$contract" --language "$language" --world closed-schema)
    compare "service-check $stem $language" service-check "${base[@]}"
    compare "service-generate $stem $language" service-generate "${base[@]}"
  done
  for language in rust ada; do
    base=(--schema "$schema" --contract "$contract" --language "$language" --world closed-schema --with-codec)
    compare "service-check --with-codec $stem $language" service-check "${base[@]}"
  done
done
echo "pairs=$pairs runs=$runs mismatches=$mismatches"
[[ "$mismatches" == 0 ]]
